local component=require("component"); local computer=require("computer"); local config=require("config.config"); local utils=require("lib.utils"); local M={last=-1e9,maxInput=0}; local file=config.dataDir.."/energyInfo.txt"; local proxy=nil
for _,n in ipairs({"flux_network","fluxnetwork","flux_controller","fluxnetworks","flux_plug"}) do if component.isAvailable(n) then proxy=component[n]; break end end; M.maxInput=utils.readNumber(file,0)
function M.update(force) local now=computer.uptime(); if not force and now-M.last<config.fluxInterval then return nil end; M.last=now; if not proxy then return {name="Flux недоступен",input=0,buffer=0,maxInput=M.maxInput} end; local info,o1=utils.safe({},function()return proxy.getNetworkInfo()end); local e,o2=utils.safe({},function()return proxy.getEnergyInfo()end); if not o1 or not o2 then return {name="Ошибка Flux",input=0,buffer=0,maxInput=M.maxInput} end; local input=tonumber(e.energyInput) or 0; if input>M.maxInput then M.maxInput=input; utils.write(file,input) end; return {name=info.name or "Без имени",input=input,buffer=tonumber(e.totalBuffer) or 0,maxInput=M.maxInput} end
return M
